/*
 * A084396  a(1) = 1; then numbers in increasing order such that the n-th
 *          partial concatenation is divisible by n.
 * https://oeis.org/A084396
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  base, nonn
 * Formula:   a(n) is defined as follows: a(1) = 1. For n > 1, a(n) is the
 *            smallest integer larger than a(n‑1) such that the decimal
 *            concatenation of a(1), a(2), …, a(n) is divisible by n. The
 *            sequence is generated by a brute‑force search using modular
 *            arithmetic
 * Range:     u8 n <= 29, u16 n <= 57, u32 n <= 57, u64 n <= 57, u128 n <= 57,
 *            big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

#include <stdlib.h>

/* Forward declaration of seq_t and idx_t – provided by the build system. */

/* Helper to compute the number of decimal digits of a seq_t value. */
static int seq_digit_len(seq_t x)
{
    if (x == 0) return 1;
    int len = 0;
    while (x > 0)
    {
        x /= 10;
        len++;
    }
    return len;
}

/* Global storage for the sequence values. */
static seq_t *a_vals = NULL;   /* array of computed terms */
static size_t a_len = 0;       /* number of terms currently stored */
static size_t a_cap = 0;       /* allocated capacity */

/* Ensure that the array can hold at least 'needed' elements. */
static void ensure_capacity(size_t needed)
{
    if (needed <= a_cap) return;
    size_t new_cap = a_cap ? a_cap * 2 : 4;
    while (new_cap < needed) new_cap *= 2;
    seq_t *new_arr = (seq_t*)malloc(new_cap * sizeof(seq_t));
    if (a_vals)
    {
        for (size_t i = 0; i < a_len; i++) new_arr[i] = a_vals[i];
        free(a_vals);
    }
    a_vals = new_arr;
    a_cap = new_cap;
}

/* Compute the modulo n of the concatenation of the first 'count' terms. */
static idx_t prefix_modulo(idx_t n, size_t count)
{
    idx_t mod = 0;
    for (size_t i = 0; i < count; i++)
    {
        seq_t val = a_vals[i];
        int d    = seq_digit_len(val);
        idx_t pow10 = 1;
        for (int j = 0; j < d; j++) pow10 = (pow10 * 10) % n;
        idx_t val_mod = (idx_t)(val % (seq_t)n);
        mod = ((mod * pow10) % n + val_mod) % n;
    }
    return mod;
}

/* Public function implementing the sequence. */
seq_t a(idx_t n)
{
    if (n == 0) return 0;               /* undefined for n == 0, but safe */
    size_t idx = (size_t)n;             /* use 0‑based index for storage */

    /* Grow storage if necessary */
    if (idx > a_cap) ensure_capacity(idx + 1);

    /* Initialize first term */
    if (idx == 1 && a_len == 0)
    {
        a_vals[0] = 1;
        a_len = 1;
        return 1;
    }

    /* Compute terms up to the requested index (in any order of calls). */
    while (a_len < idx)
    {
        size_t i = a_len;                /* position of the new term (0‑based) */
        idx_t mod_n  = (idx_t)(i + 1);    /* natural number n = i+1 */
        idx_t prev_mod = prefix_modulo(mod_n, i);   /* concat of first i terms mod n */

        seq_t candidate = a_vals[i - 1] + 1;           /* start just after previous term */
        while (1)
        {
            int d = seq_digit_len(candidate);
            idx_t pow10 = 1;
            for (int j = 0; j < d; j++) pow10 = (pow10 * 10) % mod_n;
            idx_t cand_mod = (idx_t)(candidate % (seq_t)mod_n);
            idx_t new_mod = ((prev_mod * pow10) % mod_n + cand_mod) % mod_n;
            if (new_mod == 0) break;     /* property satisfied */
            candidate++;
        }
        a_vals[i] = candidate;
        a_len++;                        /* store the new term */
    }

    return a_vals[idx - 1];
}
